python3 - <<'PY'
p='src/types/checker/inference/expr/effects.rs'
s=open(p).read()
old = """    /// Writes each by-reference array parameter's type back onto the argument variable.
    fn apply_by_ref_array_arg_types(sig: &FunctionSig, args: &[Expr], env: &mut TypeEnv) {
        for (index, arg) in args.iter().enumerate() {
            if !sig.ref_params.get(index).copied().unwrap_or(false) {
                continue;
            }
            let ExprKind::Variable(variable) = &arg.kind else {
                continue;
            };
            let Some((_, param_ty)) = sig.params.get(index) else {
                continue;
            };
            if matches!(param_ty, PhpType::Array(_) | PhpType::AssocArray { .. }) {
                env.insert(variable.clone(), param_ty.clone());
            }
        }
    }"""
new = """    /// Writes each by-reference array parameter's type back onto the argument variable.
    ///
    /// Only a CHANGE in element representation is written. Assigning the parameter type
    /// unconditionally would let a callee compiled for `array<int>` NARROW a caller that holds
    /// `array<mixed>` — the same defect in reverse, and one no call site can justify: a callee
    /// cannot unbox storage it does not own.
    fn apply_by_ref_array_arg_types(sig: &FunctionSig, args: &[Expr], env: &mut TypeEnv) {
        for (index, arg) in args.iter().enumerate() {
            if !sig.ref_params.get(index).copied().unwrap_or(false) {
                continue;
            }
            let ExprKind::Variable(variable) = &arg.kind else {
                continue;
            };
            let Some((_, param_ty)) = sig.params.get(index) else {
                continue;
            };
            if !matches!(param_ty, PhpType::Array(_) | PhpType::AssocArray { .. }) {
                continue;
            }
            let Some(current) = env.get(variable) else {
                continue;
            };
            if crate::types::checker::array_element_representation_changes(current, param_ty) {
                env.insert(variable.clone(), param_ty.clone());
            }
        }
    }"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('narrowing guard added')
